import{z as l,x as A,o as e,c as d,q as t,j as s,D as o,d as i,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Robin Hood 与布谷","description":"","frontmatter":{"title":"Robin Hood 与布谷","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/robin-cuckoo.md","filePath":"cs/robin-cuckoo.md","lastUpdated":1791063341000}'),p={name:"cs/robin-cuckoo.md"};function h(C,a,c,m,b,D){const n=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="robin-hood-与布谷" tabindex="-1">Robin Hood 与布谷 <a class="header-anchor" href="#robin-hood-与布谷" aria-label="Permalink to &quot;Robin Hood 与布谷&quot;">​</a></h1><div class="epigraph"><p>线性探测会聚集；Robin Hood 让探测距离更齐，布谷用两个表把插入变成踢人，最坏查找可以钉成常数次探测。</p><footer>—— 据 Celis, Larson and Munro, Robin Hood Hashing, FOCS 1985；Pagh and Rodler, Cuckoo Hashing, ESA 2001 / J. Algorithms 2004 整理</footer></div><p><a href="/cs/chaining-open-address">上一课</a>钉了链与开放寻址，点名线性探测聚集，并声明不引入 Cuckoo。本课不重讲 \\(\\alpha\\) 与墓碑。缺口是两种把开放寻址的探测长度压住的策略：Robin Hood 按「已走距离」抢槽；布谷散列每个键两个候选位置，插入时踢走占用者。跳表与布隆在后课，本课仍是字典的放置策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性探测成功查找的期望随 \\(\\alpha/(1-\\alpha)\\) 涨，聚集让方差很大：个别键探测很长。缺口不是换 \\(h(k)\\)——上一课函数已经均匀——而是<strong>插入时重排已有键的位置</strong>。Robin Hood：比较当前键的探测距离与槽内键的距离，远者抢槽，被抢的继续探测。查找仍沿探测序列，但最长探测距离更短、更齐。</p><p>布谷：两个散列 \\(h_1,h_2\\)，键只住两处之一。查找最多两次。插入把占用者踢到它的另一处，可能连环；过长则再散列。</p><p><span class="marginnote">布谷的「两个巢」来自布谷鸟占巢的比喻。负载通常要留空（\\(\\alpha\\) 明显小于 1），否则踢链失败频繁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Robin Hood：开放寻址 + 每槽记录或可重算的探测距离；插入时若 <code>dist(新) &gt; dist(住户)</code> 则交换。删除仍要墓碑或反向回填，回填比普通线性探测更要小心距离。</p><p>布谷：查 \\(h_1(k)\\) 与 \\(h_2(k)\\)。插：若有空则放入；否则踢出其中一个，令其去另一表对应槽，循环直到空槽或踢次数上限。</p><p><span class="marginnote">数字实例：Robin Hood 里的探测距离 dist 就是「键离它想住的第一候选槽实际走了几格」。若键想住第 17 格、最终落在第 20 格，dist 就是 3。插入时新键 dist=7 遇上住户 dist=2，就交换位置——让最惨的键少走几步，全表的最大探测距离随之变短。</span></p>',11)),(e(),s(B,null,{default:o(()=>[r(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RH%5B%22Robin%20Hood%EF%BC%9A%E8%B7%9D%E7%A6%BB%E5%A4%A7%E7%9A%84%E6%8A%A2%E6%A7%BD%22%5D%20--%3E%20OA%5B%22%E4%BB%8D%E6%98%AF%E4%B8%80%E6%9D%A1%E6%8E%A2%E6%B5%8B%E5%BA%8F%E5%88%97%22%5D%0A%20%20CU%5B%22%E5%B8%83%E8%B0%B7%EF%BC%9A%E4%B8%A4%E6%A7%BD%E4%B9%8B%E4%B8%80%22%5D%20--%3E%20KICK%5B%22%E6%8F%92%E5%85%A5%E8%B8%A2%E9%93%BE%22%5D%0A%20%20CU%20--%3E%20LOOK%5B%22%E6%9F%A5%E6%89%BE%20%E2%89%A4%202%20%E6%AC%A1%E6%8E%A2%E6%B5%8B%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"两者都改善尾部延迟，服务最坏探测比 plain 线性探测稳。Robin Hood 对 cache 仍友好（顺序探测）。布谷查找探测次数有硬上限，适合要最坏界限的硬件转发表；插入可能失败需重建，合同是「期望插入成功，失败则再散列」。",-1)),a[5]||(a[5]=E("p",null,"布谷的一次插入是如何在两个巢之间踢链、又何时放弃转去再散列：",-1)),(e(),s(B,null,{default:o(()=>[r(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E9%94%AE%20k%22%5D%20--%3E%20C1%7B%22h1%20k%20%E6%A7%BD%E4%B8%BA%E7%A9%BA%EF%BC%9F%22%7D%0A%20%20C1%20--%3E%7C%22%E7%A9%BA%22%7C%20PUT1%5B%22%E6%94%BE%E5%85%A5%20h1%EF%BC%8C%E7%BB%93%E6%9D%9F%22%5D%0A%20%20C1%20--%3E%7C%22%E5%8D%A0%E7%94%A8%22%7C%20C2%7B%22h2%20k%20%E6%A7%BD%E4%B8%BA%E7%A9%BA%EF%BC%9F%22%7D%0A%20%20C2%20--%3E%7C%22%E7%A9%BA%22%7C%20PUT2%5B%22%E6%94%BE%E5%85%A5%20h2%EF%BC%8C%E7%BB%93%E6%9D%9F%22%5D%0A%20%20C2%20--%3E%7C%22%E5%8D%A0%E7%94%A8%22%7C%20KICK%5B%22%E8%B8%A2%E8%B5%B0%E4%BD%8F%E6%88%B7%EF%BC%8C%E4%BB%A4%E5%85%B6%E5%8E%BB%E5%8F%A6%E4%B8%80%E5%B7%A2%22%5D%0A%20%20KICK%20--%3E%20LIM%7B%22%E8%B8%A2%E9%93%BE%E6%AC%A1%E6%95%B0%E8%B6%85%E8%BF%87%E4%B8%8A%E9%99%90%EF%BC%9F%22%7D%0A%20%20LIM%20--%3E%7C%22%E6%9C%AA%E8%B6%85%22%7C%20C1%0A%20%20LIM%20--%3E%7C%22%E8%B6%85%E9%99%90%22%7C%20REHASH%5B%22%E5%88%A4%E5%AE%9A%E5%A4%B1%E8%B4%A5%EF%BC%8C%E6%95%B4%E4%BD%93%E5%86%8D%E6%95%A3%E5%88%97%E6%89%A9%E8%A1%A8%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：初学者容易以为布谷的查找也可能退化成扫全表。实际上键只可能住在 \\(h_1\\) 或 \\(h_2\\) 两个槽里，查两次必出结论；代价全部转嫁给了插入——踢链可能绕圈失败，只能扩表重建。</span></p><p><span class="marginnote">直觉类比：踢链像多米诺骨牌换座位。\\(\\alpha\\) 顶满时空巢几乎不存在，换座的人永远找不到空位，队伍越排越长；留出空槽（\\(\\alpha\\) 明显小于 1）相当于礼堂里留空座，换位几步内就能坐定。</span></p><p>与链地址：\\(\\alpha\\gt 1\\) 仍只有链轻松支持。这两种都要求表内有空槽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Hopscotch、不把密码学哈希当必须。布隆过滤器下一课：<strong>不是字典</strong>，不存键本身，允许假阳性。并发 cuckoo 的位移序列是附录。</p><p>后课默认：开放寻址可用 Robin Hood 或布谷压探测尾部。只需「可能在/一定不在」且省空间，用布隆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Robin Hood 均衡探测距离；布谷把查找钉在两个位置。</li><li>插入可能重排或再散列；\\(\\alpha\\) 不能顶满。</li><li>布隆过滤器是下一课的近似集，不是精确字典。</li><li>出处：Celis et al., <em>FOCS</em>, 1985；Pagh and Rodler, <em>J. Algorithms</em>, 2004；对照 CLRS 开放寻址。</li></ul>',8))])}const k=l(p,[["render",h]]);export{_ as __pageData,k as default};
